  ('Physics', 'Edexcel', 'gcse', '2', 'Motion and Forces', 'What is Newton''s first law?', 'An object stays at rest or moves at constant velocity unless a resultant force acts on it.', 14),
  ('Physics', 'Edexcel', 'gcse', '2', 'Motion and Forces', 'What is Newton''s second law?', 'Resultant force = mass × acceleration (F = ma).', 15),
  ('Physics', 'Edexcel', 'gcse', '2', 'Motion and Forces', 'What is Newton''s third law?', 'When two objects interact, they exert equal and opposite forces on each other.', 16),
  ('Physics', 'Edexcel', 'gcse', '2', 'Motion and Forces', 'What is inertia?', 'The tendency of an object to stay at rest or keep moving at constant velocity.', 17),
  ('Physics', 'Edexcel', 'gcse', '2', 'Motion and Forces', 'What is inertial mass?', 'A measure of how difficult it is to change an object''s velocity: m = F/a.', 18),
