  ('Physics', 'OCR A', 'gcse', 'P4', 'Waves and Radioactivity', 'What happens in beta-minus decay?', 'The mass number stays the same and the atomic number increases by 1.', 30),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'Name the energy stores.', 'Kinetic, gravitational potential, elastic potential, thermal, chemical, magnetic, electrostatic and nuclear.', 1),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'Name four ways energy can be transferred.', 'Mechanically (by forces), electrically, by heating, and by radiation (light and sound).', 2),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What is the equation for kinetic energy?', 'KE = ½mv².', 3),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What is the equation for gravitational potential energy?', 'GPE = mgh.', 4),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'Calculate the KE of a 2 kg ball moving at 3 m/s.', '½ × 2 × 3² = 9 J.', 5),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'Calculate the GPE gained by a 5 kg mass lifted 2 m (g = 10 N/kg).', '5 × 10 × 2 = 100 J.', 6),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What is the law of conservation of energy?', 'Energy can''t be created or destroyed, only transferred between stores.', 7),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What is wasted energy?', 'Energy transferred to stores that aren''t useful, usually thermal energy in the surroundings.', 8),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What is efficiency?', 'Useful energy output ÷ total energy input (× 100 for a percentage).', 9),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'A motor uses 200 J and transfers 150 J usefully. What is its efficiency?', '150 ÷ 200 = 0.75, or 75%.', 10),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'How can energy waste be reduced?', 'Lubrication to reduce friction, and insulation to reduce heat loss.', 11),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What is thermal conductivity?', 'How quickly a material transfers energy by heating through conduction.', 12),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'How does the thickness of a wall affect heat loss?', 'Thicker walls reduce the rate of heat loss.', 13),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What is a Sankey diagram?', 'A diagram showing energy transfers, with arrow widths proportional to the amount of energy.', 14),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What are non-renewable energy resources?', 'Resources that will run out, e.g. coal, oil, gas and nuclear fuel.', 15),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What is work done?', 'Energy transferred when a force moves an object: W = F × d.', 16),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What is the unit of work done?', 'The joule (J).', 17),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'Calculate the work done when a 20 N force moves an object 5 m.', '20 × 5 = 100 J.', 18),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What is power?', 'The rate of doing work (energy transferred per second): P = E/t.', 19),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'Calculate the power of a motor that transfers 600 J in 20 s.', '600 ÷ 20 = 30 W.', 20),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What is 1 watt?', '1 joule of energy transferred per second.', 21),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'Why is work done against friction wasted?', 'It transfers energy to thermal stores, heating the surroundings.', 22),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What happens to energy when you push a box along the floor?', 'Work is done against friction, transferring energy to thermal energy.', 23),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What happens to energy when a car brakes?', 'Kinetic energy is transferred to thermal energy in the brakes.', 24),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'How is work done related to energy transfer?', 'Work done equals energy transferred.', 25),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What is the relationship between power, work done and time?', 'Power = work done ÷ time.', 26),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'Two motors lift the same load to the same height. One does it faster. Which is more powerful?', 'The faster one, because it transfers the same energy in less time.', 27),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What are the energy transfers for a person climbing stairs?', 'Chemical energy in muscles is transferred to GPE and thermal energy.', 28),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What are the energy transfers in an electric kettle?', 'Electrical energy is transferred to the thermal store of the water (and some wasted to the surroundings).', 29),
  ('Physics', 'OCR A', 'gcse', 'P5', 'Energy', 'What are the energy transfers in a car engine?', 'Chemical energy in fuel is transferred to kinetic energy and thermal energy (wasted).', 30),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'Give typical speeds for walking, cycling and a car in town.', 'Walking about 1.5 m/s, cycling about 6 m/s, a car in town about 13 m/s.', 1),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What is stopping distance?', 'Thinking distance + braking distance.', 2),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What factors affect thinking distance?', 'Speed and reaction time (affected by tiredness, alcohol, drugs and distractions).', 3),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What factors affect braking distance?', 'Speed, road conditions (wet or icy), and the condition of tyres and brakes.', 4),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What is a typical human reaction time?', 'About 0.2–0.9 s.', 5),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What are non-renewable energy resources?', 'Resources that will run out, e.g. coal, oil, gas and nuclear fuel.', 6),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What are renewable energy resources?', 'Resources that will be replenished, e.g. solar, wind, hydroelectric, tidal, geothermal, biofuel and wave.', 7),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'Give an advantage and disadvantage of fossil fuels.', 'Advantage: reliable and can meet demand. Disadvantage: produce CO₂ and will run out.', 8),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'Give an advantage and disadvantage of wind power.', 'Advantage: renewable, no CO₂ during operation. Disadvantage: unreliable and can be noisy or unsightly.', 9),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'Give an advantage and disadvantage of solar power.', 'Advantage: renewable, no emissions. Disadvantage: no power at night and less in cloudy weather.', 10),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'Give an advantage and disadvantage of nuclear power.', 'Advantage: no CO₂ and reliable. Disadvantage: radioactive waste and risk of accidents.', 11),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'Give an advantage and disadvantage of hydroelectric power.', 'Advantage: reliable, renewable and responds quickly. Disadvantage: floods valleys and destroys habitats.', 12),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'Give an advantage and disadvantage of tidal power.', 'Advantage: reliable and predictable. Disadvantage: few suitable sites and affects habitats.', 13),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'Why are fossil fuels still used?', 'They are reliable, the infrastructure already exists, and they can respond quickly to demand.', 14),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What is a biofuel?', 'A fuel made from plant or animal matter; it is renewable and can be carbon-neutral.', 15),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What is geothermal energy?', 'Energy from hot rocks underground, used to heat water and generate electricity.', 16),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What is the trend in UK energy use?', 'Increasing use of renewables and decreasing use of coal.', 17),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'Why is it hard to replace fossil fuels quickly?', 'Cost of new infrastructure, the reliability of supply, and public objections to some renewables.', 18),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What is the National Grid?', 'A network of cables and transformers that distributes electricity across the country.', 19),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'Why is electricity transmitted at high voltage?', 'High voltage means low current, reducing energy lost as heat in the cables.', 20),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'Where are step-up transformers used in the National Grid?', 'At power stations, to increase the voltage for transmission.', 21),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'Where are step-down transformers used in the National Grid?', 'Near homes and businesses, to reduce the voltage to a safe level (230 V).', 22),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'How are power stations connected to homes?', 'Through the National Grid: power station → step-up transformer → transmission cables → step-down transformer → homes.', 23),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What is the solar system?', 'The Sun and everything that orbits it: planets, dwarf planets, moons, asteroids and comets.', 24),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What are the eight planets in order from the Sun?', 'Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune.', 25),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What keeps planets in orbit?', 'The gravitational force of the Sun.', 26),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What is an artificial satellite?', 'A man-made object placed in orbit around the Earth, e.g. for communication or weather monitoring.', 27),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'How does orbital speed change with distance?', 'Objects closer to the body they orbit must travel faster to stay in orbit.', 28),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What is the life cycle of a star like the Sun?', 'Nebula → protostar → main sequence star → red giant → white dwarf.', 29),
  ('Physics', 'OCR A', 'gcse', 'P6', 'Global Challenges', 'What galaxy is our solar system in?', 'The Milky Way.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Physics' AND exam_board = 'OCR A' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;

-- Flashcard top-up: Physics|OCR B|alevel — brings each topic up to 30 cards.
