  ('Physics', 'OCR B', 'gcse', 'P1', 'Radiation and Waves', 'What is a wave?', 'A disturbance that transfers energy from one place to another without transferring matter.', 1),
  ('Physics', 'OCR B', 'gcse', 'P1', 'Radiation and Waves', 'What is a transverse wave?', 'A wave where the vibrations are at right angles to the direction of energy transfer, e.g. light.', 2),
  ('Physics', 'OCR B', 'gcse', 'P1', 'Radiation and Waves', 'What is a longitudinal wave?', 'A wave where the vibrations are parallel to the direction of energy transfer, e.g. sound.', 3),
