  ('Physics', 'OCR B', 'gcse', 'P1', 'Radiation and Waves', 'A wave has frequency 50 Hz and wavelength 2 m. What is its speed?', '50 × 2 = 100 m/s.', 9),
  ('Physics', 'OCR B', 'gcse', 'P1', 'Radiation and Waves', 'What is the equation linking speed, distance and time for waves?', 'v = x/t.', 10),
