  ('Physics', 'OCR B', 'gcse', 'P1', 'Radiation and Waves', 'What is reflection?', 'When a wave bounces off a surface.', 12),
  ('Physics', 'OCR B', 'gcse', 'P1', 'Radiation and Waves', 'What is the electromagnetic spectrum?', 'A continuous range of transverse waves that travel at the speed of light in a vacuum.', 13),
  ('Physics', 'OCR B', 'gcse', 'P1', 'Radiation and Waves', 'List the EM spectrum in order of increasing frequency.', 'Radio, microwaves, infrared, visible light, ultraviolet, X-rays, gamma rays.', 14),
