  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What are non-renewable energy resources?', 'Resources that will run out, e.g. coal, oil, gas and nuclear fuel.', 1),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What are renewable energy resources?', 'Resources that will be replenished, e.g. solar, wind, hydroelectric, tidal, geothermal, biofuel and wave.', 2),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'Give an advantage and disadvantage of fossil fuels.', 'Advantage: reliable and can meet demand. Disadvantage: produce CO₂ and will run out.', 3),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'Give an advantage and disadvantage of wind power.', 'Advantage: renewable, no CO₂ during operation. Disadvantage: unreliable and can be noisy or unsightly.', 4),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'Give an advantage and disadvantage of solar power.', 'Advantage: renewable, no emissions. Disadvantage: no power at night and less in cloudy weather.', 5),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'Give an advantage and disadvantage of nuclear power.', 'Advantage: no CO₂ and reliable. Disadvantage: radioactive waste and risk of accidents.', 6),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'Give an advantage and disadvantage of hydroelectric power.', 'Advantage: reliable, renewable and responds quickly. Disadvantage: floods valleys and destroys habitats.', 7),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'Give an advantage and disadvantage of tidal power.', 'Advantage: reliable and predictable. Disadvantage: few suitable sites and affects habitats.', 8),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'Why are fossil fuels still used?', 'They are reliable, the infrastructure already exists, and they can respond quickly to demand.', 9),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What is a biofuel?', 'A fuel made from plant or animal matter; it is renewable and can be carbon-neutral.', 10),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What is geothermal energy?', 'Energy from hot rocks underground, used to heat water and generate electricity.', 11),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What happens to energy when a ball is dropped?', 'GPE is transferred to KE; some is transferred to thermal energy by air resistance.', 12),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What happens to energy in a pendulum?', 'Energy is continuously transferred between GPE and KE, with some lost to the surroundings.', 13),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'How does a lubricant improve efficiency?', 'It reduces friction between moving parts, so less energy is wasted as heat.', 14),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What is the trend in UK energy use?', 'Increasing use of renewables and decreasing use of coal.', 15),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'Why is it hard to replace fossil fuels quickly?', 'Cost of new infrastructure, the reliability of supply, and public objections to some renewables.', 16),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What is a transformer?', 'A device that changes the size of an alternating voltage.', 17),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What is a step-up transformer?', 'A transformer with more turns on the secondary coil, increasing the voltage.', 18),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What is a step-down transformer?', 'A transformer with fewer turns on the secondary coil, decreasing the voltage.', 19),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What is the power equation for an ideal transformer?', 'Vp × Ip = Vs × Is.', 20),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What is the National Grid?', 'A network of cables and transformers that distributes electricity across the country.', 21),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'Why is electricity transmitted at high voltage?', 'High voltage means low current, reducing energy lost as heat in the cables.', 22),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'Where are step-up transformers used in the National Grid?', 'At power stations, to increase the voltage for transmission.', 23),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'Where are step-down transformers used in the National Grid?', 'Near homes and businesses, to reduce the voltage to a safe level (230 V).', 24),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What is the role of the iron core in a transformer?', 'It links the magnetic field between the primary and secondary coils.', 25),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'How are power stations connected to homes?', 'Through the National Grid: power station → step-up transformer → transmission cables → step-down transformer → homes.', 26),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What is work done?', 'Energy transferred when a force moves an object: W = F × d.', 27),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What is the unit of work done?', 'The joule (J).', 28),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'Calculate the work done when a 20 N force moves an object 5 m.', '20 × 5 = 100 J.', 29),
  ('Physics', 'OCR B', 'gcse', 'P2', 'Sustainable Energy', 'What is power?', 'The rate of doing work (energy transferred per second): P = E/t.', 30),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is electric current?', 'The rate of flow of charge: I = Q/t.', 1),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is potential difference?', 'The energy transferred per unit charge between two points: V = E/Q.', 2),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is resistance?', 'How much a component opposes the flow of current: R = V/I.', 3),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is Ohm''s law?', 'The current through a resistor is directly proportional to the potential difference, at constant temperature.', 4),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'Calculate the current when 12 V is applied across a 4 Ω resistor.', 'I = 12 ÷ 4 = 3 A.', 5),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'Calculate the charge that flows when 2 A flows for 30 s.', 'Q = 2 × 30 = 60 C.', 6),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is a series circuit?', 'A circuit where components are connected in a single loop.', 7),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is a parallel circuit?', 'A circuit where components are connected on separate branches.', 8),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What happens to current in a series circuit?', 'It is the same everywhere.', 9),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What happens to potential difference in a series circuit?', 'It is shared between the components.', 10),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What happens to current in a parallel circuit?', 'It is shared between the branches; the total current equals the sum of the branch currents.', 11),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What happens to potential difference in a parallel circuit?', 'It is the same across each branch.', 12),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'How do you calculate total resistance in series?', 'Add the resistances: R_total = R₁ + R₂.', 13),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What happens to total resistance when resistors are added in parallel?', 'It decreases, and is less than the smallest individual resistance.', 14),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'How is an ammeter connected?', 'In series with the component.', 15),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'How is a voltmeter connected?', 'In parallel across the component.', 16),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is the I–V graph for a fixed resistor?', 'A straight line through the origin.', 17),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is the I–V graph for a filament lamp?', 'A curve that gets less steep, because resistance increases as the filament heats up.', 18),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is the I–V graph for a diode?', 'Current flows in one direction only, after a small threshold voltage.', 19),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'How does the resistance of a thermistor change?', 'It decreases as temperature increases.', 20),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'How does the resistance of an LDR change?', 'It decreases as light intensity increases.', 21),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is electrical power?', 'P = IV = I²R.', 22),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is the motor effect?', 'A current-carrying wire in a magnetic field experiences a force.', 23),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is Fleming''s left-hand rule?', 'First finger = field, second finger = current, thumb = motion (force).', 24),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is the equation for the force on a wire in a magnetic field?', 'F = B × I × l.', 25),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is magnetic flux density?', 'A measure of the strength of a magnetic field, measured in tesla (T).', 26),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'Calculate the force on a 0.5 m wire carrying 2 A in a 0.1 T field.', 'F = 0.1 × 2 × 0.5 = 0.1 N.', 27),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'How does an electric motor work?', 'Current in a coil in a magnetic field creates forces on opposite sides in opposite directions, making the coil rotate.', 28),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'What is the role of the split-ring commutator?', 'It reverses the current every half turn, so the coil keeps rotating in the same direction.', 29),
  ('Physics', 'OCR B', 'gcse', 'P3', 'Electric Circuits', 'How can the speed of a motor be increased?', 'Increase the current, use a stronger magnet, or add more turns to the coil.', 30),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is speed?', 'The distance travelled per unit time: speed = distance ÷ time.', 1),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is velocity?', 'Speed in a given direction.', 2),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is acceleration?', 'The rate of change of velocity: a = (v − u) ÷ t.', 3),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is the unit of acceleration?', 'm/s².', 4),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What does the gradient of a distance–time graph show?', 'Speed.', 5),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What does a horizontal line on a distance–time graph show?', 'The object is stationary.', 6),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What does the gradient of a velocity–time graph show?', 'Acceleration.', 7),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What does the area under a velocity–time graph show?', 'Distance travelled.', 8),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What does a horizontal line on a velocity–time graph show?', 'Constant velocity.', 9),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is the equation linking v, u, a and x?', 'v² − u² = 2ax.', 10),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'A car accelerates from 10 m/s to 30 m/s in 5 s. What is its acceleration?', '(30 − 10) ÷ 5 = 4 m/s².', 11),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is the acceleration due to gravity near Earth''s surface?', 'About 10 m/s² (9.8 m/s²).', 12),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'Give typical speeds for walking, cycling and a car in town.', 'Walking about 1.5 m/s, cycling about 6 m/s, a car in town about 13 m/s.', 13),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is Newton''s first law?', 'An object stays at rest or moves at constant velocity unless a resultant force acts on it.', 14),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is Newton''s second law?', 'Resultant force = mass × acceleration (F = ma).', 15),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is Newton''s third law?', 'When two objects interact, they exert equal and opposite forces on each other.', 16),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is inertia?', 'The tendency of an object to stay at rest or keep moving at constant velocity.', 17),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is inertial mass?', 'A measure of how difficult it is to change an object''s velocity: m = F/a.', 18),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is a resultant force?', 'The single force that has the same effect as all the forces acting on an object.', 19),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'How do you calculate the resultant of two forces in the same direction?', 'Add them.', 20),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'How do you calculate the resultant of two forces in opposite directions?', 'Subtract the smaller from the larger; the resultant acts in the direction of the larger.', 21),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What happens if the resultant force is zero?', 'The object stays at rest or continues at constant velocity.', 22),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is a contact force?', 'A force that acts when objects are touching, e.g. friction, air resistance, tension and normal contact force.', 23),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is a non-contact force?', 'A force that acts at a distance, e.g. gravity, magnetism and electrostatic force.', 24),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is a free-body force diagram?', 'A diagram showing all the forces acting on a single object, with arrows showing size and direction.', 25),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'How can forces be resolved?', 'By splitting a force into two perpendicular components, e.g. horizontal and vertical.', 26),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is a moment?', 'The turning effect of a force: moment = force × perpendicular distance from the pivot.', 27),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is the unit of a moment?', 'Newton metre (N m).', 28),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'What is the principle of moments?', 'For an object in equilibrium, the sum of clockwise moments equals the sum of anticlockwise moments.', 29),
  ('Physics', 'OCR B', 'gcse', 'P4', 'Explaining Motion', 'A 10 N force acts 0.5 m from a pivot. What is the moment?', '10 × 0.5 = 5 N m.', 30),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is the structure of an atom?', 'A small, dense, positively charged nucleus containing protons and neutrons, surrounded by electrons.', 1),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What are the relative charges of protons, neutrons and electrons?', 'Proton +1, neutron 0, electron −1.', 2),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What are the relative masses of protons, neutrons and electrons?', 'Proton 1, neutron 1, electron about 1/1840.', 3),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is the atomic number?', 'The number of protons in the nucleus.', 4),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is the mass number?', 'The total number of protons and neutrons in the nucleus.', 5),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is an isotope?', 'Atoms of the same element with the same number of protons but different numbers of neutrons.', 6),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is radioactive decay?', 'The random process in which an unstable nucleus emits radiation to become more stable.', 7),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is an alpha particle?', 'Two protons and two neutrons (a helium nucleus).', 8),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is a beta-minus particle?', 'A fast-moving electron emitted from the nucleus when a neutron turns into a proton.', 9),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is a positron?', 'A particle with the same mass as an electron but a positive charge, emitted in beta-plus decay.', 10),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is gamma radiation?', 'High-frequency electromagnetic radiation emitted from the nucleus.', 11),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is the penetrating power of alpha, beta and gamma?', 'Alpha is stopped by paper, beta by a few mm of aluminium, gamma is reduced by thick lead or concrete.', 12),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is the ionising power of alpha, beta and gamma?', 'Alpha is highly ionising, beta moderately, gamma weakly.', 13),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What happens in alpha decay?', 'The mass number decreases by 4 and the atomic number decreases by 2.', 14),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What happens in beta-minus decay?', 'The mass number stays the same and the atomic number increases by 1.', 15),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What happens in gamma emission?', 'No change to mass number or atomic number; the nucleus loses energy.', 16),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is half-life?', 'The time taken for the number of radioactive nuclei (or activity) to halve.', 17),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is activity?', 'The rate at which a source decays, measured in becquerels (Bq).', 18),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'A sample has activity 800 Bq and half-life 2 hours. What is the activity after 6 hours?', 'Three half-lives: 800 → 400 → 200 → 100 Bq.', 19),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is background radiation?', 'Radiation that is always around us from natural and man-made sources.', 20),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'Name three sources of background radiation.', 'Radon gas, rocks, cosmic rays, food, and medical X-rays.', 21),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is irradiation?', 'Exposing an object to radiation; the object does not become radioactive.', 22),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is contamination?', 'When radioactive atoms get onto or into an object.', 23),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'How can workers be protected from radiation?', 'Shielding, keeping distance, limiting exposure time, and monitoring doses.', 24),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'How is radiation used in medicine?', 'Radiotherapy to kill cancer cells, tracers to diagnose problems, and sterilising equipment.', 25),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What did the plum pudding model suggest?', 'The atom was a ball of positive charge with electrons embedded in it.', 26),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What did the alpha scattering experiment show?', 'Most of the atom is empty space and there is a small, dense, positive nucleus.', 27),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'How did Bohr improve the atomic model?', 'He suggested electrons orbit the nucleus in fixed energy levels (shells).', 28),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What happens when an electron moves to a higher energy level?', 'It absorbs electromagnetic radiation.', 29),
  ('Physics', 'OCR B', 'gcse', 'P5', 'Radioactive Materials', 'What is nuclear fission?', 'Splitting a large nucleus into smaller nuclei, releasing energy and neutrons.', 30),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is density?', 'Mass per unit volume: ρ = m/V.', 1),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the unit of density?', 'kg/m³ (or g/cm³).', 2),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'Calculate the density of a 200 g block with volume 100 cm³.', '200 ÷ 100 = 2 g/cm³.', 3),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'How can the density of an irregular object be found?', 'Measure its mass with a balance and its volume by displacement of water in a measuring cylinder.', 4),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the particle arrangement in a solid?', 'Particles are closely packed in a regular pattern, vibrating about fixed positions.', 5),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the particle arrangement in a liquid?', 'Particles are close together but randomly arranged and can move past each other.', 6),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the particle arrangement in a gas?', 'Particles are far apart, randomly arranged and move quickly in all directions.', 7),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'Why are gases less dense than solids?', 'The particles are much further apart.', 8),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is internal energy?', 'The total kinetic and potential energy of all the particles in a system.', 9),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What happens to internal energy when a substance is heated?', 'It increases, either raising the temperature or changing the state.', 10),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is specific heat capacity?', 'The energy needed to raise the temperature of 1 kg of a substance by 1 °C.', 11),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the equation for specific heat capacity?', 'ΔQ = m × c × Δθ.', 12),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'Calculate the energy needed to heat 2 kg of water by 10 °C (c = 4200 J/kg°C).', '2 × 4200 × 10 = 84,000 J.', 13),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is specific latent heat?', 'The energy needed to change the state of 1 kg of a substance without a change in temperature.', 14),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the equation for specific latent heat?', 'Q = m × L.', 15),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the specific latent heat of fusion?', 'The energy needed to change 1 kg from solid to liquid.', 16),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the specific latent heat of vaporisation?', 'The energy needed to change 1 kg from liquid to gas.', 17),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'Why does temperature stay constant during a change of state?', 'The energy is used to break bonds between particles, not to increase kinetic energy.', 18),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is melting?', 'Changing from solid to liquid.', 19),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is evaporation?', 'Changing from liquid to gas at the surface of a liquid, below its boiling point.', 20),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is elastic deformation?', 'When an object returns to its original shape after the force is removed.', 21),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is inelastic (plastic) deformation?', 'When an object doesn''t return to its original shape after the force is removed.', 22),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is Hooke''s law?', 'The extension of a spring is directly proportional to the force applied, up to the limit of proportionality.', 23),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the equation for Hooke''s law?', 'F = k × x.', 24),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the spring constant?', 'The force needed to stretch a spring by 1 m, measured in N/m.', 25),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'Calculate the force needed to stretch a spring with k = 50 N/m by 0.2 m.', '50 × 0.2 = 10 N.', 26),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the limit of proportionality?', 'The point beyond which extension is no longer proportional to force.', 27),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What is the energy stored in a stretched spring?', 'E = ½kx² (elastic potential energy).', 28),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'Calculate the energy stored in a spring with k = 100 N/m stretched 0.1 m.', '½ × 100 × 0.1² = 0.5 J.', 29),
  ('Physics', 'OCR B', 'gcse', 'P6', 'Matter — Models and Explanations', 'What does the gradient of a force–extension graph show?', 'The spring constant.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Physics' AND exam_board = 'OCR B' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;

COMMIT;
